-- Dansk portion 7 del 2/3: 167 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 3343-6573.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish7'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish7', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":3343,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Årets Sundby-løb samlede 340 børn søndag. Vejret var koldt, men stemningen var god. Vinderen hos pigerne var 11-årige Amina Ali, der også vandt sidste år. Efter målstregen delte løbets frivillige bananer og varm kakao ud.' Hvad var særligt ved Amina Alis sejr?","o":["Hun var den yngste i hele løbet","Hun løb hurtigere end drengene","Hun vandt, selvom det var koldt","Hun vandt også året før"],"a":"Hun vandt også året før","r":"Teksten siger, at hun også vandt sidste år. Den nævner hverken de andre løberes alder eller drengenes tider."},
{"l":3362,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er budskabet i ordsproget 'Ærlighed varer længst'?","o":["Det betaler sig at sige sandheden","De, der siger sandheden, bliver rige","Gamle ting holder bedre end nye","Det tager lang tid at lære at tale pænt"],"a":"Det betaler sig at sige sandheden","r":"Ordsproget siger, at man i det lange løb kommer bedst ud af det ved at være ærlig, også selvom løgnen kan virke lettere."},
{"l":3385,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"To elever har begge glemt deres lektier. Den ene siger: 'Vi sidder i samme båd.' Hvad mener han?","o":["De skal på ferie sammen","De har det samme problem","De er uvenner med hinanden","De er gode til at svømme"],"a":"De har det samme problem","r":"Sidder man i samme båd, er man i den samme situation. Tit er det en svær situation."},
{"l":3400,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Amina gik langsomt hjem. Hun tænkte på Jonas, og hun var ked af det.' Hvilken fortæller har teksten?","o":["førstepersonsfortæller","andenpersonsfortæller","tredjepersonsfortæller","vi-fortæller"],"a":"tredjepersonsfortæller","r":"Fortælleren siger 'hun' om Amina og står uden for historien. Med 'jeg' ville det have været en førstepersonsfortæller."},
{"l":3422,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Læreren siger, at Amira gør 'fremskridt' i matematik. Hvad betyder det?","o":["Hun regner hurtigere end de andre","Hun sidder forrest i klassen","Hun er gået videre til en ny bog","Hun bliver bedre og bedre"],"a":"Hun bliver bedre og bedre","r":"Et fremskridt er et skridt frem mod noget bedre. Det handler om Amiras egen udvikling, ikke om, hvordan hun klarer sig i forhold til andre."},
{"l":3443,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg hele udsagnsleddet i: 'Hunden har gravet et hul i haven.'","o":["har gravet","Hunden","et hul","i haven"],"a":"har gravet","r":"Udsagnsleddet er her to udsagnsord, der hører sammen: 'har' og 'gravet'."},
{"l":3465,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Udfyld: 'Efter vinteren var hun blevet ___ i armene.'","o":["stærkkere","stærkere","stærkre","sterkere"],"a":"stærkere","r":"Højere grad dannes her med -ere. Ordet har æ og kun ét k."},
{"l":3486,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hver tirsdag hjalp Nora sin nabo fru Holm med at vande blomsterne på altanen. I dag fyldte Nora tolv, og da hun kom hjem, stod der en potte med en gul rose på dørmåtten. På sedlen stod der: Den har jeg selv dyrket, for jeg ved, at gul er din yndlingsfarve. Til min lille hjælper. Nora smilede hele vejen ind i stuen.' Hvorfor bliver Nora så glad?","o":["Hun slipper for at vande blomster fra nu af","Hun skal passe fru Holms blomster i morgen","Fru Holm har husket, hvilken farve hun elsker","Fru Holm har købt den dyreste rose i butikken"],"a":"Fru Holm har husket, hvilken farve hun elsker","r":"Fru Holm har selv dyrket rosen og husket, at Nora elsker gul. Det er det, der gør gaven så god."},
{"l":3505,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Et gammelt brev kan fortælle os om fortiden. Hvad kalder historikere sådan noget?","o":["en fabel","en gåde","en myte","en kilde"],"a":"en kilde","r":"En kilde er alt, der kan give os viden om fortiden: breve, billeder, ting og fortællinger fra dengang."},
{"l":3522,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hvor gammelt er et træ? Når træet vokser, laver det hvert år en ny ring under barken. I varme, våde år bliver ringen bred, og i kolde, tørre år bliver den smal. Ved at tælle ringene på en stub kan man finde træets alder.' Hvad kan du slutte, hvis en stub har en meget smal ring?","o":["At det år var koldt og tørt","At træet blev fældet det år","At træet var syv år gammelt det år","At det år var varmt og vådt"],"a":"At det år var koldt og tørt","r":"Teksten siger, at ringen bliver smal i kolde, tørre år. I varme, våde år bliver den bred."},
{"l":3542,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form af 'at knuse' passer: 'Vinduet blev ___ af en bold.'","o":["knuste","knust","knuser","knusende"],"a":"knust","r":"Efter 'blev' står her den korte tillægsform. 'Knuste' er datid eller flertal og passer ikke til ét vindue."},
{"l":3564,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg det ord, der passer: 'Danmark består af mange ___.'","o":["ører","øere","øer","øger"],"a":"øer","r":"Ental er 'ø', og flertal får bare -er. Ordet er meget kort, men helt rigtigt."},
{"l":3585,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Flagermus jager om natten. De sender høje lyde ud og lytter til det ekko, der kommer tilbage. Sådan kan de høre, hvor insekterne er, selv i bælgmørke. Mennesker kan næsten ikke høre lydene, for de er for høje for vores ører.' Hvad er det vigtigste redskab, flagermusen bruger, når den jager?","o":["Sit gode nattesyn","Sin høje fart","Sin lugtesans","Sin hørelse"],"a":"Sin hørelse","r":"Flagermusen finder føden ved at lytte til ekko, altså med ørerne. Nattesyn nævnes ikke."},
{"l":3602,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket navneord dannet af 'ven' betyder det bånd, der er mellem to gode venner?","o":["venskab","venlighed","vennekreds","veninde"],"a":"venskab","r":"Venskab er det, man har sammen, når man er gode venner. Det samme gælder naboskab mellem naboer. En vennekreds er derimod en gruppe af venner."},
{"l":3619,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find det ubestemte stedord: 'Ingen fandt skatten i haven.'","o":["fandt","Ingen","skatten","haven"],"a":"Ingen","r":"'Ingen' peger ikke på en bestemt person. Det er derfor et ubestemt stedord."},
{"l":3641,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find bindeordet: 'Vi gik en tur, selvom det blæste.'","o":["gik","tur","selvom","blæste"],"a":"selvom","r":"'Selvom' binder to sætninger sammen og viser, at noget sker på trods af noget andet."},
{"l":3662,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at have 'en finger med i spillet'?","o":["at slå sig under en håndboldkamp","at være god til at spille klaver","at pege på den, der har gjort det","at være med til at påvirke noget"],"a":"at være med til at påvirke noget","r":"Har man en finger med i spillet, har man været med til at få noget til at ske, ofte uden at det er tydeligt for andre."},
{"l":3682,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Mens resten af klassen var på tur sad Emil hjemme med feber.'?","o":["tur","klassen","sad","hjemme"],"a":"tur","r":"Ledsætningen er 'Mens resten af klassen var på tur'. Hovedsætningen begynder med 'sad'."},
{"l":3700,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kan stå i stedet for 'kendsgerning' i: 'Det er en kendsgerning, at vand fryser ved nul grader.'","o":["gætteri","faktum","mening","gåde"],"a":"faktum","r":"En kendsgerning og et faktum er begge noget, man ved er sandt. En mening er noget, man selv synes."},
{"l":3720,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken af sætningerne om farmor er direkte tale og skal have anførselstegn?","o":["Farmor sagde, at nu var hendes kage færdig","Farmor bagte en kage, og nu er den færdig","Nu er min kage færdig, sagde farmor","Farmor fortalte, at kagen nu var færdig"],"a":"Nu er min kage færdig, sagde farmor","r":"'min' og 'er' viser, at det er farmors egne ord, og de skal i anførselstegn. Med 'at' fortæller man bare, hvad hun sagde."},
{"l":3740,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er den rigtige form? 'Hvem har ___ dit hår så flot?'","o":["klipet","klippede","klipt","klippet"],"a":"klippet","r":"Efter 'har' ender ordet på -et. P'et er dobbelt, fordi i'et er kort."},
{"l":3760,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad forstår man ved 'tidevand'?","o":["at havet regelmæssigt stiger og falder","at bølgerne bliver høje under en storm","at havet fryser til is om vinteren","at floderne tørrer ud om sommeren"],"a":"at havet regelmæssigt stiger og falder","r":"Tidevandet skyldes især Månens tiltrækning. I Vadehavet kan man tydeligt se forskel på ebbe og flod."},
{"l":3781,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Klara sad længe med sedlen. Der stod: Det var mig. Undskyld. Den lå i hendes penalhus, og nogen havde taget hendes viskelæder i mandags. Hele ugen havde Josefine været mærkeligt stille. Klara kiggede over på hende, og Josefine så hurtigt ned.' Hvad er Klaras mistanke?","o":["At læreren har lagt sedlen i hendes penalhus","At Josefine har skrevet sedlen","At hun selv har glemt, at hun har skrevet den","At Josefine er sur, fordi nogen har taget hendes ting"],"a":"At Josefine har skrevet sedlen","r":"Klara ser på Josefine, som har været stille og nu slår blikket ned. Det viser, at hun tror, Josefine er afsender."},
{"l":3797,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betød det, at Danmark fra 1660 havde 'enevælde'?","o":["Folket valgte selv sine ledere","Adelen bestemte over kongen","Kongen havde al magten alene","Kirken styrede hele landet"],"a":"Kongen havde al magten alene","r":"Ene betyder alene, og vælde betyder magt. Enevælden varede til 1849, hvor Danmark fik sin første grundlov."},
{"l":3817,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Uret tilhører Aksel. Hvilket ord passer: 'Aksel har mistet ___ ur.'","o":["sin","sine","hans","sit"],"a":"sit","r":"Det hedder et ur, så ordet skal være 'sit'. 'Hans' ville pege på en anden dreng."},
{"l":3839,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form af 'at købe' passer: 'Vi havde ___ billetter, før vi gik hen til biografen.'","o":["købt","købte","køber","købe"],"a":"købt","r":"'Havde' kræver tillægsform, og det giver førdatid. 'Købte' er datid."},
{"l":3860,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvem har skrevet 'Gummi-Tarzan'?","o":["H.C. Andersen","Ole Lund Kirkegaard","Halfdan Rasmussen","Thorbjørn Egner"],"a":"Ole Lund Kirkegaard","r":"Ole Lund Kirkegaard var en dansk børnebogsforfatter. Han skrev også 'Otto er et næsehorn' og 'Hodja fra Pjort'."},
{"l":3880,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad skal stå på stregen: 'Emil havde dårlig ___, fordi han havde løjet for sin mor.'","o":["hukommelse","kondition","samvittighed","ånde"],"a":"samvittighed","r":"Samvittigheden er den indre stemme, der siger, om man har handlet rigtigt. Man får dårlig samvittighed, når man ved, man har gjort noget forkert."},
{"l":3898,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Min bror mener, at computerspil er spild af tid. Det er jeg uenig i. Når vi spiller sammen, lærer vi at samarbejde og tale engelsk. Selvfølgelig skal man også lave noget andet. Men jeg synes ikke, at spil er værre end at se fjernsyn.' Hvilket argument bruger skribenten for computerspil?","o":["At spil er sjovere end at se fjernsyn","At spil giver gode karakterer i matematik","At man ikke behøver at lave andet end at spille","At man lærer noget af at spille sammen"],"a":"At man lærer noget af at spille sammen","r":"Skribenten nævner samarbejde og engelsk. De andre påstande står ikke i teksten."},
{"l":3916,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Udfyld: 'Jeg har ___ en gammel mønt på vejen.'","o":["fundet","funnet","fundt","findet"],"a":"fundet","r":"Efter 'har' skifter i til u, og ordet staves med nd, selvom d'et ikke høres."},
{"l":3938,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find stavemåden: 'Koret har ___ smukt i kirken i aften.'","o":["sungt","sunget","synget","sunnet"],"a":"sunget","r":"Ordet 'synge' skifter y til u efter 'har', og det ender på -et."},
{"l":3955,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Morten er bange for at komme for sent. Far siger: 'Der er ingen ko på isen.' Hvad mener far?","o":["Der er for koldt til at gå ud","Der er ingen vej uden om","Der er ingen grund til bekymring","Der er noget helt galt på gården"],"a":"Der er ingen grund til bekymring","r":"En ko på isen er i stor fare. Er der ingen ko på isen, er der ikke noget at være bange for."},
{"l":3977,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'mikro-' i ord som 'mikroskop' og 'mikrochip'?","o":["meget stor","elektrisk","gennemsigtig","meget lille"],"a":"meget lille","r":"Mikro kommer fra græsk og betyder lille. Et mikroskop bruges til at se meget små ting."},
{"l":4000,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord mangler: 'Malthe træner hver dag, fordi han drømmer om at nå landsholdet. Han er meget ___.'","o":["ambitiøs","overfladisk","ligeglad","uheldig"],"a":"ambitiøs","r":"Den ambitiøse har høje mål og arbejder hårdt for at nå dem."},
{"l":4015,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg rigtigt: 'Hver morgen ___ jeg bageren på vej til skole.'","o":["passere","passerer","paserer","passeret"],"a":"passerer","r":"Sætningen er i nutid, og ord på -ere får endelsen -erer. Ordet staves med dobbelt s."},
{"l":4037,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Vi ___ dig med dagen!'","o":["gratulere","gradulerer","gratulerer","gratuleret"],"a":"gratulerer","r":"Det sker nu, så ordet ender på -erer. Det staves med t, selvom det kan lyde som d."},
{"l":4059,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find hovedsætningen: 'Da solen gik ned, tændte vi lys.'","o":["Da solen gik ned","solen gik ned","Da solen","tændte vi lys"],"a":"tændte vi lys","r":"'Da solen gik ned' er ledsætning, fordi den begynder med et bindeord og ikke kan stå alene. Resten er hovedsætningen, hvor udsagnsleddet står først."},
{"l":4080,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvilket budskab har 'Den grimme ælling'?","o":["Man skal ikke dømme andre på udseendet","Man skal blive i den gård, man er født i","Den, der er stærkest, klarer sig bedst","Man skal gøre det samme som de andre"],"a":"Man skal ikke dømme andre på udseendet","r":"Ællingen ser anderledes ud end de andre. Til sidst viser det sig, at den var noget særligt hele tiden."},
{"l":4097,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kaldes det, når to forskellige arter lever tæt sammen, og begge har gavn af det?","o":["parasitisme","symbiose","konkurrence","nedbrydning"],"a":"symbiose","r":"Ved symbiose får begge noget ud af samarbejdet, som når en svamp og en alge lever sammen i en lav. Ved parasitisme er det kun den ene, der får gavn."},
{"l":4115,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Alt gik galt for Hamza, lige til han fandt det gamle brev i skuffen. Fra den dag ændrede alt sig.' Hvad kaldes sådan et sted i en historie?","o":["en indledning","en afslutning","et vendepunkt","en beskrivelse"],"a":"et vendepunkt","r":"Et vendepunkt er det sted, hvor handlingen tager en ny retning. Her skifter historien fra uheld til noget nyt."},
{"l":4136,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvordan staves ordet i sætningen? 'Vores næste ___ i skemaet er matematik.'","o":["lektjon","leksion","lekstion","lektion"],"a":"lektion","r":"Endelsen -tion lyder som 'sjon', men staves med t."},
{"l":4157,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Vælg det rigtige ord: 'Kun de ældste elever havde det ___ at måtte gå ud af skolen i frikvarteret.'","o":["privilegium","overskud","fællesskab","hensyn"],"a":"privilegium","r":"Et privilegium er en særlig ret, som kun nogle har, og som andre må undvære."},
{"l":4176,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Skal man have mobil i frikvarteret? Min klasse stemte ja, fordi man kan aftale noget og høre musik. Men vores lærer viste os tal fra en anden skole. Her legede eleverne dobbelt så meget, efter at mobilerne blev samlet ind. Det har fået mig til at tænke, og nu er jeg ikke så sikker mere.' Hvad mener skribenten nu?","o":["Skribenten synes nu, at mobiler skal forbydes","Skribenten er i tvivl på grund af tallene","Skribenten er blevet mere sikker på sit ja","Skribenten mener det samme som før"],"a":"Skribenten er i tvivl på grund af tallene","r":"Sætningen 'ikke så sikker mere' viser tvivl. Skribenten har ikke skiftet side helt, men er blevet usikker."},
{"l":4195,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er meningen med ordsproget 'Som man reder, ligger man'?","o":["Man bør rede sin seng hver eneste morgen","Man skal sove længe for at klare sig godt i livet","Man må leve med følgerne af det, man selv har gjort","Man kan ikke gøre noget ved det, andre beslutter"],"a":"Man må leve med følgerne af det, man selv har gjort","r":"Har du redt sengen dårligt, ligger du dårligt. Ordsproget siger, at dine egne valg bestemmer, hvordan du får det senere."},
{"l":4213,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ordenstal passer: 'Farfar fylder 60, så det er hans ___ fødselsdag.'","o":["halvtredsindstyvende","halvfjerdsindstyvende","firsindstyvende","tresindstyvende"],"a":"tresindstyvende","r":"'Tres' er 60, og ordenstallet hedder 'tresindstyvende'. 'Halvtredsindstyvende' hører til 50, 'halvfjerdsindstyvende' til 70, og 'firsindstyvende' til 80."},
{"l":4233,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om hjælp fra tre venner er helt rigtig?","o":["Hvis du spørger Ida, Mads eller Clara, kan de hjælpe dig.","Hvis du spørger Ida Mads, eller Clara kan de hjælpe dig.","Hvis du spørger, Ida Mads eller Clara kan de hjælpe dig.","Hvis du spørger Ida, Mads, eller Clara kan de hjælpe dig."],"a":"Hvis du spørger Ida, Mads eller Clara, kan de hjælpe dig.","r":"Opremsningen skal have komma efter 'Ida', og hele ledsætningen slutter efter 'Clara'. Foran 'eller' skal der ikke stå komma."},
{"l":4255,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Skolen 'fejede problemet ind under gulvtæppet'. Hvad gjorde skolen?","o":["Den løste problemet, så ingen mere talte om det","Den skjulte problemet i stedet for at løse det","Den gjorde rent i alle klasselokaler om morgenen","Den fortalte alle forældre om problemet med det samme"],"a":"Den skjulte problemet i stedet for at løse det","r":"Skidtet forsvinder ikke, fordi det ligger under tæppet. Vendingen betyder, at man gemmer et problem væk uden at gøre noget ved det."},
{"l":4271,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken tekst om turen med bussen er skrevet helt rigtigt?","o":["Da bussen standsede råbte, chaufføren: »Alle skal af!« Vi tog tasker, jakker og madkasser.","Da bussen standsede, råbte chaufføren »: Alle skal af!« Vi tog tasker jakker, og madkasser.","Da bussen standsede, råbte chaufføren: »Alle skal af!« Vi tog tasker, jakker og madkasser.","Da bussen standsede, råbte chaufføren: »Alle skal af?« Vi tog tasker, jakker, og madkasser."],"a":"Da bussen standsede, råbte chaufføren: »Alle skal af!« Vi tog tasker, jakker og madkasser.","r":"Teksten har komma efter ledsætningen, kolon før den direkte tale, udråbstegn i råbet og komma i opremsningen, men ikke foran 'og'."},
{"l":4295,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Vinden hviskede i træerne, og månen smilede til byen.' Hvad kaldes det, når ting opfører sig som levende væsener?","o":["overdrivelse","bogstavrim","gentagelse","besjæling"],"a":"besjæling","r":"Vinden kan ikke hviske, og månen kan ikke smile. Når ting får menneskelige træk, kaldes det besjæling."},
{"l":4318,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord er det modsatte af 'midlertidig'?","o":["varig","foreløbig","tilfældig","forsigtig"],"a":"varig","r":"Noget midlertidigt gælder kun et stykke tid, mens noget varigt bliver ved. 'Foreløbig' betyder næsten det samme som midlertidig."},
{"l":4334,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt ind: 'Han er en ___ dreng, som altid hjælper til.'","o":["ordenlig","ordentlig","ordentli","ornlig"],"a":"ordentlig","r":"Ordet kommer af 'orden'. Der er et t foran -lig, selvom det ikke høres i talesprog."},
{"l":4355,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord er et verbum: 'Den vilde ræv løber ind i skoven.'","o":["vilde","ræv","løber","skoven"],"a":"løber","r":"Verbum er det latinske navn for udsagnsord. 'Løber' fortæller, hvad ræven gør."},
{"l":4377,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"'Bag' er et forholdsord i sætningen 'Cyklen står bag skuret.' Hvad hedder ordklassen på latin?","o":["konjunktion","pronomen","adverbium","præposition"],"a":"præposition","r":"Præposition er det latinske ord for forholdsord. 'Præ' betyder 'foran', fordi ordet står foran det, det hører til."},
{"l":4394,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Termometeret viser, at ___ er faldet til tre grader.'","o":["temperaturen","tempraturen","temparaturen","temperatturen"],"a":"temperaturen","r":"Ordet har fire stavelser før endelsen, og det tryksvage e efter p skal med. Der er kun ét t efter a."},
{"l":4414,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Løven lod musen gå. Senere gnavede musen nettet over og reddede løven.' Hvad er moralen i fablen?","o":["De stærkeste klarer sig altid selv","Også de små kan hjælpe de store","Mus skal holde sig fra løver","Det er farligt at gå i et net"],"a":"Også de små kan hjælpe de store","r":"Løven troede ikke, at en mus kunne hjælpe den. Fablen viser, at selv den mindste kan gøre en stor forskel."},
{"l":4432,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken sætning er 'Malou rydder op.' sat i førdatid?","o":["Malou har ryddet op.","Malou ryddede op.","Malou havde ryddet op.","Malou var ryddet op."],"a":"Malou havde ryddet op.","r":"Førdatid består af 'havde' og tillægsform. 'Har ryddet' er førnutid, og 'ryddede' er datid."},
{"l":4454,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Det danske ___ har 29 bogstaver.'","o":["alphabet","alfabæt","allfabet","alfabet"],"a":"alfabet","r":"På dansk skrives f-lyden f, og ordet slutter på -bet med e."},
{"l":4475,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er 'privatliv'?","o":["den del af livet, der er ens egen sag","det arbejde, man har i et privat firma","det hus, man selv ejer og bor i","den tid, man bruger i offentlig transport"],"a":"den del af livet, der er ens egen sag","r":"Privatlivet er det, andre ikke har krav på at vide noget om. Derfor må man ikke dele billeder af andre uden lov."},
{"l":4490,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Udfyld: 'En sodavandsdåse har form som en ___.'","o":["sylinder","cylinder","cyllinder","cylinter"],"a":"cylinder","r":"Ordet begynder med c, som lyder som s foran y. Det har ét l og ét d."},
{"l":4510,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Mumitroldene er skrevet af Tove Jansson. Hvilket land kom hun fra?","o":["Norge","Island","Finland","Sverige"],"a":"Finland","r":"Tove Jansson var finsk og skrev på svensk. Hun både skrev og tegnede bøgerne om Mumitroldene."},
{"l":4531,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at lyve': 'Ræven har ___ for de andre dyr.'","o":["løj","lyver","lyve","løjet"],"a":"løjet","r":"'At lyve' er uregelmæssigt: lyver, løj, har løjet. Efter 'har' står tillægsformen."},
{"l":4550,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'De første tog i Danmark kørte i 1840’erne. Før havde en rejse fra Kolding til København kunnet tage flere dage. Da jernbanen blev udbygget, kunne folk nå det på under et døgn. Det ændrede også handlen: Friske varer kunne pludselig sælges langt væk, inden de blev dårlige.' Hvad er tekstens hovedemne?","o":["Hvordan jernbanen ændrede rejser og handel","Hvordan togene fik damp til at drive hjulene","Hvorfor Kolding er en vigtig by i Danmark","Hvorfor friske varer er sundere end andre"],"a":"Hvordan jernbanen ændrede rejser og handel","r":"Teksten viser to ændringer, som jernbanen førte med sig: kortere rejsetid og ny handel."},
{"l":4574,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"To venner viser hinanden 'gensidig' respekt. Hvad betyder det?","o":["at kun den ene viser respekt for den anden","at de begge viser respekt for den anden","at de kun viser respekt, når andre ser det","at de har vist hinanden respekt én gang"],"a":"at de begge viser respekt for den anden","r":"Noget gensidigt går begge veje: Hver af parterne giver det samme til den anden."},
{"l":4594,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Ida gør tre ting efter hinanden. Hvilken sætning er kommateret rigtigt?","o":["Ida stod op spiste morgenmad, og gik i skole.","Ida stod op, spiste morgenmad, og gik i skole.","Ida stod op, spiste morgenmad og gik i skole.","Ida, stod op, spiste morgenmad og gik i skole."],"a":"Ida stod op, spiste morgenmad og gik i skole.","r":"Handlingerne er en opremsning med samme grundled. Der er komma mellem dem, men ikke foran det sidste 'og'."},
{"l":4605,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vi tror, at vi ved, hvad vi selv ville gøre. 6.B spurgte 40 voksne på gågaden, om de ville hjælpe en fremmed, der tabte sine papirer. Næsten alle sagde ja. Men da en elev bagefter tabte en bunke papirer samme sted, stoppede kun hver fjerde. Mange sagde, at de havde travlt.' Hvad viser forsøget?","o":["At de fleste hjælper, når nogen taber noget","At folk har for travlt til at svare på spørgsmål","At mennesker hjælper mest, når de har travlt","At folk tit handler anderledes, end de tror"],"a":"At folk tit handler anderledes, end de tror","r":"Der er stor forskel på det, folk sagde, og det, de gjorde. Det er forsøgets pointe."},
{"l":4627,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Efter finalen sagde træneren, at det havde været en 'fair' kamp. Hvad mente han?","o":["at den var retfærdig og fulgte reglerne","at den var spændende helt til det sidste","at den var hård og fuld af frispark","at den var kort og hurtigt overstået"],"a":"at den var retfærdig og fulgte reglerne","r":"Fair er lånt fra engelsk og betyder retfærdig. En fair kamp spilles ærligt og efter reglerne."},
{"l":4646,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Udfyld sætningen: 'Efter skole går nogle elever i ___.'","o":["fritidklub","fritidsklub","fritidsclub","fritids klub"],"a":"fritidsklub","r":"Ordet har fuge-s efter 'fritid', og 'klub' staves med k på dansk."},
{"l":4665,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hver lørdag hjalp Viktor kioskejeren med at bære aviser ind. Han ville ikke have noget for det. En eftermiddag rakte kioskejeren ham hans yndlingsblad og sagde: – Det her er blevet for gammelt til at sælge. Bladet var fra samme morgen.' Hvad har kioskejeren gjort?","o":["Han har narret Viktor til at købe et blad","Han har givet Viktor et gammelt blad fra sidste uge","Han har fundet på en grund til at give Viktor bladet","Han har fundet et blad, der blev glemt i kiosken"],"a":"Han har fundet på en grund til at give Viktor bladet","r":"Bladet er fra samme morgen, så det er ikke gammelt. Viktor vil ikke have noget for hjælpen, så kioskejeren finder på en undskyldning."},
{"l":4685,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Forskere har længe undret sig over, at fugle kan finde vej over tusindvis af kilometer. De bruger solen og stjernerne, men de har også en sans for Jordens magnetfelt. Man ved ikke helt, hvordan den virker. Forsøg tyder på, at sansen har noget at gøre med fuglens øjne.' Hvad er endnu usikkert ifølge teksten?","o":["Om fugle flyver mange kilometer om året","Om fugle bruger stjerner til at finde vej","Om Jorden har et magnetfelt","Præcis hvordan magnetsansen fungerer"],"a":"Præcis hvordan magnetsansen fungerer","r":"Ordene 'man ved ikke helt' og 'tyder på' viser, hvad forskerne endnu ikke er sikre på."},
{"l":4700,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Nadia havde øvet sig på talen i tre uger. Da hun stod på scenen, kunne hun høre sit eget hjerte, og papiret i hånden raslede som en fugl, der ville væk.' Hvad fortæller sammenligningen med fuglen?","o":["At hendes hånd ryster af nervøsitet","At der er kommet en fugl ind i salen","At hun helst vil smide papiret ud","At papiret er ved at gå i stykker"],"a":"At hendes hånd ryster af nervøsitet","r":"Papiret rasler, fordi hånden ryster. Billedet med fuglen, der vil væk, viser også, at Nadia selv helst ville flygte."},
{"l":4718,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg rigtigt: 'Tryllekunstneren viste et ___ trick.'","o":["forbløfende","forbløffende","forbløffene","forblyffende"],"a":"forbløffende","r":"Ordet har dobbelt f, fordi ø'et er kort, og lang tillægsform ender på -ende."},
{"l":4740,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Da vi kom, ___ filmen allerede begyndt.'","o":["er","bliver","var","være"],"a":"var","r":"'Da vi kom' er datid, og filmen begyndte endnu tidligere. Så skal der stå førdatid med 'var'."},
{"l":4762,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find forholdsordsleddet: 'Hun tænker tit på sin hest.'","o":["sin hest","tit på sin hest","tænker","på sin hest"],"a":"på sin hest","r":"'På' er forholdsordet, og 'sin hest' hører til det. Sammen udgør de et forholdsordsled."},
{"l":4778,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Hesten er ___ over hegnet.'","o":["sprunget","sprungt","springet","sprungget"],"a":"sprunget","r":"I'et fra 'springe' bliver til u i kort tillægsform, og ordet ender på -et."},
{"l":4799,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Ordene 'venskab' og 'fjendskab' ender på det samme. Hvilket ord med samme endelse betyder 'det at eje noget'?","o":["fællesskab","ejerskab","lederskab","landskab"],"a":"ejerskab","r":"Endelsen -skab laver navneord, der beskriver en tilstand eller et forhold. Ejerskab er det at være ejer."},
{"l":4815,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da hunden blev gammel og ikke længere kunne gå op ad trappen, begyndte Sebastian at sove nedenunder på sofaen. Han sagde, at det var, fordi der var bedre plads. Men han fik ondt i ryggen af sofaen og sov dårligt. Hunden sov roligt ved siden af ham.' Hvorfor sover Sebastian egentlig nedenunder?","o":["Fordi der er bedre plads på sofaen end i sengen","Fordi han har fået ondt i ryggen af at sove ovenpå","Fordi han vil være sammen med sin gamle hund","Fordi trappen er blevet for svær for ham selv"],"a":"Fordi han vil være sammen med sin gamle hund","r":"Hans forklaring holder ikke: Han sover dårligt på sofaen. Den egentlige grund er hunden."},
{"l":4837,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord ligger tættest på 'opslugt' i sætningen 'Hun var helt opslugt af bogen'?","o":["forskrækket","fornærmet","forarget","fordybet"],"a":"fordybet","r":"Den, der er opslugt af noget, er så optaget af det, at alt andet forsvinder. Det svarer til at være fordybet."},
{"l":4855,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord mangler der komma i udråbet 'Av det gjorde ondt!'","o":["Av","det","gjorde","ondt"],"a":"Av","r":"Et udråbsord som 'av' står løst foran sætningen og skal skilles fra den med komma."},
{"l":4874,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Hvilken ___ har den røde knap?'","o":["funksjon","funktion","fungtion","funsion"],"a":"funktion","r":"Lånord med k-lyd før endelsen skrives -ktion."},
{"l":4894,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find hovedsætningen: 'Far siger, at vi skal rydde op.'","o":["at vi skal rydde op","vi skal rydde op","Far siger","skal rydde op"],"a":"Far siger","r":"'At vi skal rydde op' begynder med et bindeord og er ledsætningen. Den fortæller, hvad far siger."},
{"l":4912,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Skoleballet blev en 'fiasko'. Hvordan gik det?","o":["det gik over al forventning","det blev udsat en uge","det sluttede meget sent","det gik helt galt"],"a":"det gik helt galt","r":"En fiasko er noget, der mislykkes totalt. Det modsatte kaldes en succes."},
{"l":4934,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Astronauternes ___ var at reparere satellitten.'","o":["mission","mistion","misjon","mision"],"a":"mission","r":"Ordet ender på -ssion med dobbelt s, selvom det lyder som 'sjon'."},
{"l":4952,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Alle har kaldt vores fodboldklub for en underskudsforretning, siden vi købte de nye lamper. Men sidste år kom der 40 nye medlemmer, fordi de kan træne om aftenen om vinteren. Hvad angår økonomien, så er kontingenterne fra dem netop nok til at betale lampernes strømregning. Det er ingen underskudsforretning.' Hvad er skribentens argument?","o":["At strømmen er blevet billigere for alle fodboldklubber i år","At de nye medlemmer betaler for lampernes strøm","At klubben har fået for mange medlemmer om vinteren","At kritikerne har ret i, at lamperne var alt for dyre"],"a":"At de nye medlemmer betaler for lampernes strøm","r":"Skribenten bruger tal: De nye medlemmers kontingent dækker strømmen. Derfor afviser skribenten kritikken."},
{"l":4972,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord giver mening her? 'Hans forklaring var så ___, at ingen tvivlede på den.'","o":["forvirrende","mistænkelig","overbevisende","usammenhængende"],"a":"overbevisende","r":"Noget overbevisende får andre til at tro på det. Det passer til, at ingen var i tvivl."},
{"l":4993,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken forkortelse for 'klokken' er rigtig i: 'Vi mødes ___ 10 ved hallen.'?","o":["k.l.","klk.","klo.","kl."],"a":"kl.","r":"Ordet klokken forkortes kl. med ét punktum, fordi det kun er ét ord."},
{"l":5006,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Personen spiller klaver til koncerter. Hvad er stavet rigtigt?","o":["pianist","pjanist","pianisst","pianiest"],"a":"pianist","r":"Ordet har i efter p og ét n. Det ender på -ist."},
{"l":5026,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at måtte': 'Vi har ___ vente på bussen i en time.'","o":["måtte","måttet","må","skulle"],"a":"måttet","r":"'Har' kræver tillægsform, og af 'at måtte' hedder den 'måttet' med -t. Fejlen 'har måtte' er meget almindelig."},
{"l":5047,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad vil det sige at 'have rent mel i posen'?","o":["at have bagt noget lækkert til hele familien","at have styr på sin økonomi og sine regninger","at være ærlig og ikke have noget at skjule","at være forsigtig med alt, hvad man foretager sig"],"a":"at være ærlig og ikke have noget at skjule","r":"Billedet er mel, der ikke er blandet op med noget andet. Man kan altså stole på personen."},
{"l":5066,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Lærerne var på ___ i Odense i to dage.'","o":["konferense","konfærence","konferance","konference"],"a":"konference","r":"Ordet ender på -ence med e og c."},
{"l":5085,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad vil det sige at søge 'asyl'?","o":["at bede om beskyttelse i et andet land","at søge arbejde hos en stor virksomhed","at bede om en ny dato til en eksamen","at ansøge om at få udstedt et nyt pas"],"a":"at bede om beskyttelse i et andet land","r":"Asyl betyder et fristed. Det søges af mennesker, der ikke kan være i sikkerhed i deres hjemland."},
{"l":5105,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvem skrev sangen 'I Danmark er jeg født'?","o":["N.F.S. Grundtvig","H.C. Andersen","B.S. Ingemann","Adam Oehlenschläger"],"a":"H.C. Andersen","r":"H.C. Andersen skrev ikke kun eventyr, men også digte og sange. Denne sang er en kærlighedserklæring til Danmark."},
{"l":5126,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning slutter rigtigt med en forkortelse?","o":["Vi skal købe mælk, brød, ost osv..","Vi skal købe mælk, brød, ost os.v.","Vi skal købe mælk, brød, ost osv.","Vi skal købe mælk, brød, ost. osv."],"a":"Vi skal købe mælk, brød, ost osv.","r":"Når en forkortelse slutter sætningen, gør dens punktum også det ud for sætningens punktum. Der skal kun ét."},
{"l":5145,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Landets 'elite' i svømning mødes i Aarhus. Hvem er det?","o":["de allerstørste","de nye medlemmer","de frivillige hjælpere","de allerbedste"],"a":"de allerbedste","r":"Eliten er de bedste inden for et område. Ordet kommer af fransk og betyder de udvalgte."},
{"l":5164,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'Vi fejrer juleaften hos doktor Holm på nørregade i Aalborg.'?","o":["nørregade","juleaften","doktor","fejrer"],"a":"nørregade","r":"Vejnavne er navne og får stort. Mærkedage som juleaften og titler som doktor skrives med lille."},
{"l":5183,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken skrivemåde er rigtig: 'Han fandt en gammel ___ på loftet.'? Det er en maskine, der spiller musik fra skiver.","o":["cd afspiller","cd-afspiller","c.d.afspiller","cdafspiller"],"a":"cd-afspiller","r":"Når en forkortelse sættes sammen med et ord, skrives der bindestreg imellem."},
{"l":5202,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken flertalsform er rigtig: 'Der står ti ___ i computerlokalet.'?","o":["pcer","pc-er","pc'er","pc.er"],"a":"pc'er","r":"Når en forkortelse bøjes, sætter man apostrof foran endelsen."},
{"l":5222,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Noor havde glemt sin madpakke på skovturen. Uden at sige noget delte Malthe sin i to og gav hende den ene halvdel.' Hvilket tema passer bedst?","o":["sult og mad","skovture og natur","glemsomhed og rod","venskab og hjælpsomhed"],"a":"venskab og hjælpsomhed","r":"Temaet er det, teksten egentlig handler om. Det er ikke madpakken, men at Malthe hjælper sin ven uden at blive bedt om det."},
{"l":5245,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Forholdsord hører sammen med det, der står efter dem. Hvad hører 'ved' sammen med i: 'Vi bor ved havet om sommeren.'","o":["havet","om sommeren","bor","Vi"],"a":"havet","r":"'Ved' står foran 'havet', og sammen fortæller de, hvor vi bor. Det, der hører til et forholdsord, kaldes også forholdsordets styrelse."},
{"l":5265,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Efter at bussen var kørt, 'stod Kasper med håret i postkassen'. Hvad betyder det?","o":["han ventede utålmodigt på et vigtigt brev","han stod i en knibe uden en god løsning","han havde lige været til frisør i byen","han var kommet for sent hjem fra ferie"],"a":"han stod i en knibe uden en god løsning","r":"Det er et billedligt udtryk for at sidde fast i en ubehagelig situation, hvor man ikke kan komme videre."},
{"l":5282,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Her venter du, når du skal med bybussen. Hvordan staves stedet?","o":["bustoppested","bus stoppested","busstoppested","busstopsted"],"a":"busstoppested","r":"Ordet er sammensat af 'bus' og 'stoppested'. Derfor står der to s'er i træk."},
{"l":5300,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Cecilie: Vi bør have færre prøver, for de stresser eleverne. Hassan: Prøverne skal blive, men eleverne skal forberedes bedre på dem.' Hvad er forskellen på de to forslag?","o":["Cecilie vil have flere prøver, Hassan vil have færre","Cecilie taler om lærerne, Hassan taler om eleverne","Cecilie vil fjerne stress, Hassan vil gerne øge den","Cecilie vil have færre prøver, Hassan vil have bedre forberedelse"],"a":"Cecilie vil have færre prøver, Hassan vil have bedre forberedelse","r":"Cecilie vil skære i antallet, mens Hassan bevarer prøverne og flytter fokus. Begge søger en løsning, men et forskelligt sted."},
{"l":5311,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Find den indskudte ledsætning: 'Bilen, som holdt foran huset, var rød.'","o":["som holdt foran huset","Bilen var rød","Bilen, som holdt","foran huset"],"a":"som holdt foran huset","r":"Ledsætningen er skudt ind i hovedsætningen 'Bilen var rød' og fortæller, hvilken bil det er."},
{"l":5332,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'som følge af' i sætningen 'Skolen lukkede som følge af stormen'?","o":["på trods af","på grund af","i stedet for","lige inden"],"a":"på grund af","r":"'Som følge af' angiver en årsag. Skolen lukkede, fordi der var storm."},
{"l":5354,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Du må ___ gerne låne min blyant.'","o":["naturlivis","naturligtvis","naturligvis","naturlig vis"],"a":"naturligvis","r":"Ordet skrives i ét, og der er intet t foran -vis."},
{"l":5370,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hun var en 'pioner' inden for dansk kvindeidræt. Hvad betyder det?","o":["hun var en af de sidste, der holdt fast i det gamle","hun var en, der kun skrev om andres resultater","hun var en, der stod for økonomien i klubben","hun var en af de første, der gjorde noget nyt"],"a":"hun var en af de første, der gjorde noget nyt","r":"En pioner baner vejen for andre. Ordet blev først brugt om soldater, der ryddede vej for de andre."},
{"l":5390,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt ind: 'Turen varer ___ en time.'","o":["omtrent","omtrænt","omtret","omtrendt"],"a":"omtrent","r":"Ordet staves med e og ender på -nt uden d."},
{"l":5407,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord ligger tættest på 'fremtrædende' i udtrykket 'en fremtrædende forsker'?","o":["fremmed","anerkendt","nyuddannet","fremtidig"],"a":"anerkendt","r":"En fremtrædende forsker skiller sig positivt ud og er kendt og respekteret for sit arbejde."},
{"l":5430,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord er komma et krav: 'Hvis du vil have at vi kommer må du sige til i god tid.'?","o":["vi","må","kommer","sige"],"a":"kommer","r":"Hele ledsætningen 'Hvis du vil have at vi kommer' slutter efter 'kommer', og efter en ledsætning skal der komma."},
{"l":5449,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord skal have stort: 'Vi sejlede gennem lillebælt og spiste en dansk is på færgen.'?","o":["dansk","færgen","is","lillebælt"],"a":"lillebælt","r":"Lillebælt er navnet på et bestemt farvand og skrives derfor med stort. 'Dansk' er et tillægsord og skrives med lille."},
{"l":5468,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning er rigtig om hunden, der larmede om natten?","o":["Hunden, der gøede hele natten, tilhører naboen.","Hunden, der gøede hele natten tilhører naboen.","Hunden der gøede, hele natten tilhører naboen.","Hunden der gøede hele natten tilhører, naboen."],"a":"Hunden, der gøede hele natten, tilhører naboen.","r":"Ledsætningen 'der gøede hele natten' står inde i hovedsætningen og skal afsluttes med komma efter 'natten'."},
{"l":5487,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken form er rigtig: 'Jeg sendte to ___ til min kusine.'?","o":["smser","sms'er","sms-er","sms.er"],"a":"sms'er","r":"Forkortelser får apostrof foran endelsen, når de bøjes."},
{"l":5506,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'kritisk' i sætningen 'Klubbens økonomi var i en kritisk fase'?","o":["negativ og vurderende","rolig og stabil","farlig og afgørende","afsluttet og overstået"],"a":"farlig og afgørende","r":"I en kritisk fase kan det gå begge veje. 'Kritisk' kan også betyde vurderende, men det passer ikke om økonomi her."},
{"l":5525,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Tre af sætningerne mangler et komma. Hvilken er skrevet rigtigt?","o":["Da vi kom til Odense tog vi en bus videre.","Hvis toget er forsinket ringer vi hjem.","Når vi er fremme spiser vi frokost.","I morgen tidlig tager vi toget til Odense."],"a":"I morgen tidlig tager vi toget til Odense.","r":"'I morgen tidlig' er et tidsled og ikke en ledsætning. De tre andre begynder med en ledsætning og skal have komma efter den."},
{"l":5544,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord skal have stort: 'Min onkel er kok på kronborg og taler flydende svensk.'?","o":["kronborg","onkel","kok","svensk"],"a":"kronborg","r":"Kronborg er navnet på et bestemt slot. Stillinger som kok og sprog som svensk skrives med lille."},
{"l":5564,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Cyklen var Sannes. Hvilket ord passer: 'Sanne gav sin bror ___ gamle cykel.'","o":["hendes","sin","hans","deres"],"a":"sin","r":"Cyklen tilhører grundleddet Sanne. 'Sin' kan godt bruges to gange i samme sætning, når begge peger på hende."},
{"l":5582,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Klassen havde læst et digt om en sten på en strand. Mads sagde, at det handlede om en sten. Læreren spurgte, hvorfor digteren så havde brugt 20 linjer på en sten. Mads tænkte sig om og sagde: – Måske er det ikke stenen, der er vigtig. Det er, at nogen stoppede op og så på den.' Hvad har Mads lært i løbet af samtalen?","o":["At digte altid handler om sten og strande","At læreren ved mere om sten, end han selv gør","At et digt kan betyde mere, end det siger direkte","At 20 linjer er for meget til et godt digt"],"a":"At et digt kan betyde mere, end det siger direkte","r":"Mads går fra det bogstavelige til det, digtet kan betyde: at stoppe op og se det små."},
{"l":5603,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"For at forstå sætningen må man kende dens 'kontekst'. Hvad er det?","o":["den person, der har skrevet den","den vigtigste del af sætningen","den oversættelse, den har fået","den sammenhæng, den står i"],"a":"den sammenhæng, den står i","r":"Konteksten er det, der står omkring noget. Den samme sætning kan betyde noget forskelligt i to sammenhænge."},
{"l":5622,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Tænk på en vej mellem to byer i Grønland. Der er ikke nogen. Tænk på en butik uden kø. Tænk på en dag, hvor solen aldrig går ned. Sådan begynder rejsebogen om Ilulissat, og skribenten skriver det ikke for at sælge rejser, men fordi hun aldrig selv helt forstod det. Bogen er ikke en guide, men et brev til den, hun var før rejsen.' Hvad er særligt ved bogen?","o":["Den handler mest om, hvordan rejsen ændrede forfatteren","Den er først og fremmest en reklame for rejser til Grønland","Den er en praktisk håndbog i at finde vej rundt i Grønland","Den er en samling af breve skrevet af grønlandske børn"],"a":"Den handler mest om, hvordan rejsen ændrede forfatteren","r":"'Et brev til den, hun var før rejsen' viser, at bogen handler om, hvordan rejsen ændrede hende."},
{"l":5642,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'En ___ er en voldsom storm med kraftig vind.'","o":["syklon","cyklon","cyklonn","cycklon"],"a":"cyklon","r":"Ordet begynder med c og y og ender på ét n."},
{"l":5663,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det, at en person er 'forfængelig'?","o":["at personen er bange for at blive fanget","at personen er meget venlig mod fremmede","at personen er optaget af sit eget udseende","at personen er hurtig til at tilgive"],"a":"at personen er optaget af sit eget udseende","r":"Den forfængelige vil gerne beundres. Bland ikke ordet sammen med 'forgængelig', som betyder noget andet."},
{"l":5682,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Skoleavisen bragte en artikel med overskriften: Eleverne elsker den nye skolemad. Artiklen byggede på en samtale med tre elever, som kokken havde valgt ud. I vores klasse, 7.A, viste en håndsoprækning, at de fleste stadig smører madpakke. Så hvem er det egentlig, der elsker den nye skolemad?' Hvad kritiserer skribenten artiklen for?","o":["At overskriften er for lang til en skoleavis","At kokken selv har skrevet hele artiklen","At den ikke fortæller, hvad maden koster","At den kun bygger på tre elever, som kokken har valgt"],"a":"At den kun bygger på tre elever, som kokken har valgt","r":"Tre elever, valgt af kokken, kan ikke tale for alle. Derfor holder overskriften ikke."},
{"l":5702,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg det rigtige ord: 'Min tante dufter af en dyr ___.'","o":["parfume","parfyme","parfumme","perfume"],"a":"parfume","r":"Ordet er fransk, har u efter f og ét m."},
{"l":5723,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I Folketinget taler man om 'oppositionen'. Hvem er det?","o":["de ministre, der leder landet","de partier, der ikke er med i regeringen","de dommere, der sidder i Højesteret","de embedsmænd, der skriver lovforslag"],"a":"de partier, der ikke er med i regeringen","r":"Oppositionen står uden for regeringen og holder øje med den. Ordet kommer af 'opponere', som betyder at sætte sig imod."},
{"l":5746,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Friktion' er et ord fra fysikken. Hvad beskriver det?","o":["kraften, der trækker alle ting ned mod jorden","varmen, der kommer fra solens stråler","modstanden, når to flader gnider mod hinanden","energien, der er gemt i et batteri"],"a":"modstanden, når to flader gnider mod hinanden","r":"Friktion er gnidningsmodstand. Den gør, at dine sko kan få fat i gulvet, og at en bil kan bremse."},
{"l":5761,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Emil vil købe cyklen med det samme, men hans mor siger: 'Klap lige hesten.' Hvad mener hun?","o":["at han skal skynde sig at købe den","at han slet ikke må købe den","at han skal låne penge til den","at han skal slappe af og tænke sig om"],"a":"at han skal slappe af og tænke sig om","r":"Man klapper en urolig hest for at berolige den. Talemåden betyder, at man skal falde ned og ikke forhaste sig."},
{"l":5784,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Den gamle bus stønnede op ad bakken og sukkede lettet på toppen.' Hvilket virkemiddel bruger forfatteren?","o":["personifikation","sammenligning","allitteration","ironi"],"a":"personifikation","r":"Bussen får menneskelige handlinger: Den stønner og sukker. Når en ting får menneskelige træk, kaldes det personifikation."},
{"l":5801,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Stille står stenene på stranden.' Hvilket virkemiddel er tydeligst i linjen?","o":["sammenligning","allitteration","ironi","metafor"],"a":"allitteration","r":"Flere ord begynder med den samme lyd, st-. Det kaldes allitteration eller bogstavrim."},
{"l":5821,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad vil det sige at 'se nogen i kortene'?","o":["at spille kort med en person hele aftenen","at forudsige en persons fremtid med spillekort","at finde ud af, hvad en person har planer om","at blive gode venner med en person hurtigt"],"a":"at finde ud af, hvad en person har planer om","r":"Billedet kommer fra kortspil, hvor det er en stor fordel at kende modstanderens kort. Det har intet at gøre med spådom."},
{"l":5840,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning om ravstenen fra stranden er tegnsat rigtigt?","o":["På vej hjem fra stranden, fandt vi en ravsten.","På vej hjem, fra stranden fandt vi en ravsten.","På vej, hjem fra stranden fandt vi en ravsten.","På vej hjem fra stranden fandt vi en ravsten."],"a":"På vej hjem fra stranden fandt vi en ravsten.","r":"Første del har intet udsagnsled og er ikke en ledsætning, selvom den er lang. Så der skal ikke komma."},
{"l":5860,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket klokkeslæt er skrevet rigtigt i skemaet?","o":["kl. 14.30","kl, 14.30","kl. 14,30","k.l. 14.30"],"a":"kl. 14.30","r":"'Kl.' er en forkortelse med ét punktum, og timer og minutter adskilles med punktum, ikke komma."},
{"l":5881,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'En ræv har i flere uger sovet under cykelskurene på Havnegades Skole. Pedellen har døbt den Svend. Kommunen anbefaler, at man ikke fodrer den.' Hvad antyder kommunens anbefaling?","o":["At ræven er syg og snart bliver fjernet af kommunen","At nogen kunne finde på at give ræven mad","At pedellen ikke må give ræven et navn","At skolen er bange for rævens unger"],"a":"At nogen kunne finde på at give ræven mad","r":"Man advarer kun mod noget, der kan ske. Så må kommunen regne med, at nogen måske vil fodre ræven."},
{"l":5900,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Pressemeddelelse: Busrute 12 optimeres fra næste måned. Med færre afgange skabes en mere enkel og overskuelig køreplan.' Hvad betyder det i praksis for passagererne?","o":["Bussen får en mere direkte rute","Bussen bliver billigere at tage","Bussen kommer sjældnere end før","Bussen kommer oftere end før"],"a":"Bussen kommer sjældnere end før","r":"'Optimeres' lyder positivt, men 'færre afgange' fortæller, hvad der reelt sker. Pressemeddelelsen får en dårligere køreplan til at lyde som noget godt."},
{"l":5920,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvem har skrevet romanen 'Busters verden' fra 1979?","o":["Ole Lund Kirkegaard","Cecil Bødker","Astrid Lindgren","Bjarne Reuter"],"a":"Bjarne Reuter","r":"'Busters verden' er en af Bjarne Reuters mest kendte bøger. Den blev også til en film af Bille August."},
{"l":5941,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"På en blanket skal du skrive din 'bopæl'. Hvad skal du oplyse?","o":["hvor du bor","hvor du er født","hvor du går i skole","hvor din familie stammer fra"],"a":"hvor du bor","r":"Bopæl er det formelle ord for det sted, man bor. Det bruges af myndigheder, for eksempel i folkeregisteret."},
{"l":5960,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Mens Zainab spillede klaver lavede hendes bror mad.'?","o":["spillede","klaver","lavede","bror"],"a":"klaver","r":"'Mens Zainab spillede klaver' er en ledsætning, og den slutter efter 'klaver'."},
{"l":5980,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning er skrevet rigtigt om skolens to ferier?","o":["Skolen holder lukket i sommer og -vinterferien.","Skolen holder lukket i sommer-og vinterferien.","Skolen holder lukket i sommer- og vinterferien.","Skolen holder lukket i sommer -og vinterferien."],"a":"Skolen holder lukket i sommer- og vinterferien.","r":"Ordet 'ferien' er sparet væk efter 'sommer'. Bindestregen viser det og står tæt efter 'sommer'."},
{"l":6000,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hvorfor læser vi stadig gamle romaner? Fordi de viser, at mennesker for 100 år siden også var ensomme, forelskede og flove.' Hvilket svar giver teksten?","o":["De viser, at livet var sværere for mennesker før i tiden","De viser, hvordan folk talte og klædte sig i gamle dage","De viser, at nutidens bøger er ringere end de gamle","De viser, at folk dengang havde de samme følelser som os"],"a":"De viser, at folk dengang havde de samme følelser som os","r":"Ordet 'også' viser, at folk for 100 år siden var ensomme, forelskede og flove ligesom os."},
{"l":6013,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hver aften hentede Bilal sin lillebror fra fritidshjemmet, lavede mad og satte vasketøj over. Læreren skrev i hans bog, at han skulle gøre mere ud af sine lektier. Han læste beskeden, mens gryden kogte.' Hvad vil teksten få læseren til at tænke?","o":["At læreren ikke kender hele Bilals hverdag","At Bilal bevidst snyder sig uden om lektierne","At lillebroren burde klare sig helt selv","At Bilal hellere vil være kok end elev"],"a":"At læreren ikke kender hele Bilals hverdag","r":"Bilal henter sin lillebror, laver mad og vasker tøj hver aften. Læreren skriver, at han skal gøre mere ud af lektierne. Det lyder, som om læreren ikke ved, hvad han bruger aftenen på."},
{"l":6035,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Freja: Skolefesten bør holdes fredag, for så kan alle sove længe dagen efter. Oskar: Skolefesten bør holdes torsdag, for fredag har mange af os håndboldkamp.' Hvad er Freja og Oskar enige om?","o":["At alle skal kunne sove længe","At der skal holdes en skolefest","At håndbold er vigtigere end festen","At torsdag er den bedste dag"],"a":"At der skal holdes en skolefest","r":"De diskuterer dagen, ikke selve festen. Begge går altså ud fra, at festen skal holdes."},
{"l":6056,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Regnen piskede mod ruderne, og mørket lagde sig tungt over det øde hus.' Hvilken stemning skaber beskrivelsen?","o":["Lun og hyggelig","Drømmende og stille","Uhyggelig og truende","Kedelig og ensformig"],"a":"Uhyggelig og truende","r":"Ord som 'piskede', 'mørket', 'tungt' og 'øde' skaber en truende stemning. Forfatteren bruger miljøet til at sætte stemningen."},
{"l":6073,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad vil det sige, at en fortælling er kronologisk?","o":["Begivenhederne fortælles fra enden mod starten","Fortælleren springer frem og tilbage hele tiden","Handlingen foregår i en meget fjern fremtid","Begivenhederne kommer i den rækkefølge, de sker"],"a":"Begivenhederne kommer i den rækkefølge, de sker","r":"Kronologi betyder tidsfølge. I en kronologisk fortælling følger handlingen tiden fra først til sidst."},
{"l":6093,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning indeholder en bydeform?","o":["Stil din cykel ved muren.","Stiller du din cykel ved muren?","Stillede du din cykel ved muren?","Hvis du stiller din cykel ved muren."],"a":"Stil din cykel ved muren.","r":"'Stil' er en direkte opfordring og står i bydeform, og bydeformen har normalt ikke noget grundled. 'Stiller du …?' begynder også med verbet, men det er et spørgsmål med grundleddet 'du'."},
{"l":6107,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad betyder det, at en tekst begynder in medias res?","o":["Den begynder med en lang beskrivelse af miljøet","Den begynder midt i handlingen uden forklaring","Den begynder med fortællerens egen barndom","Den begynder med at præsentere hver person"],"a":"Den begynder midt i handlingen uden forklaring","r":"In medias res er latin for 'midt i tingene'. Læseren kastes direkte ind i handlingen, og det er typisk for noveller."},
{"l":6126,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken type stedord er 'Denne' i: 'Denne opgave er den sværeste i hæftet.'?","o":["personligt stedord","spørgende stedord","påpegende stedord","gensidigt stedord"],"a":"påpegende stedord","r":"'Denne' peger på noget bestemt, næsten som hvis man pegede med en finger. Det kaldes også et demonstrativt stedord."},
{"l":6148,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning bruger 'nogen' eller 'nogle' rigtigt i skriftsprog?","o":["Vi så nogen flotte heste på marken.","Hun har ikke nogle bror.","Er der nogle læge til stede?","Vi så nogle flotte heste på marken."],"a":"Vi så nogle flotte heste på marken.","r":"I en bekræftende sætning med flertal skrives 'nogle'. 'Bror' og 'læge' står i ental og kan ikke have 'nogle' foran sig."},
{"l":6170,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Hun kom ___ ned ad trappen.'?","o":["løbende","løbene","løbet","løber"],"a":"løbende","r":"'Komme' sammen med lang tillægsform viser, hvordan man kommer. Lang tillægsform ender på -ende, mens 'løbene' er flertal af navneordet 'løb'."},
{"l":6192,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kaldes den del af et argument, som afsenderen vil have modtageren til at acceptere?","o":["belæg","påstand","hjemmel","patos"],"a":"påstand","r":"Påstanden er det synspunkt, der argumenteres for. Belægget er begrundelsen, og hjemlen forbinder de to."},
{"l":6201,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find den rigtige form: 'Uhyret i filmen var virkelig ___.'","o":["skræmmene","skræmende","skræmmende","skrammende"],"a":"skræmmende","r":"Ordet er dannet af 'skræmme' med -ende. Husk dobbelt-m og d'et."},
{"l":6222,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Forskere har talt fugle i samme skov i 30 år. Antallet af nogle arter er faldet, mens andre er steget. Skoven er i samme periode blevet tættere, og flere gamle træer står tilbage.' Hvad kan man slutte med sikkerhed?","o":["Den tættere skov har drevet nogle fugle væk","Klimaet er årsag til de nye fuglearter","Der er nu flere fugle i alt end før","Fuglebestanden har ændret sig i de 30 år"],"a":"Fuglebestanden har ændret sig i de 30 år","r":"Teksten viser ændringen, men ikke årsagen, og heller ikke det samlede antal. Kun forandringen er sikker."},
{"l":6241,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er 'tolerance' over for andre mennesker?","o":["viljen til at acceptere, at andre tænker anderledes","evnen til at overbevise andre om, at man har ret","trangen til altid at gøre, hvad flertallet siger","ønsket om at holde sig helt for sig selv"],"a":"viljen til at acceptere, at andre tænker anderledes","r":"At være tolerant er at tåle og respektere andres holdninger og levevis, også når man selv er uenig."},
{"l":6260,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Mira glædede sig, så det kildede i maven. Hun kunne næsten ikke vente med at prøve den høje vippe.' Hvad får læseren adgang til her?","o":["Det, Mira gør og siger","Det, Mira tænker og føler","Det, andre tænker om hende","Det, fortælleren mener om Mira"],"a":"Det, Mira tænker og føler","r":"Teksten viser, hvad der foregår inde i Mira. Det kaldes en indre synsvinkel."},
{"l":6286,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Slanger er 'vekselvarme'. Hvad betyder det?","o":["deres kropstemperatur er altid den samme","de skifter hud, når det bliver varmt","deres kropstemperatur følger omgivelserne","de kan kun leve i meget varme lande"],"a":"deres kropstemperatur følger omgivelserne","r":"Vekselvarme dyr kan ikke selv holde en fast kropstemperatur. Derfor lægger slanger sig i solen for at blive varme."},
{"l":6300,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Min gade sover. / Kun en cykel ligger vågen / med forhjulet snurrende.' Hvad kan læseren slutte?","o":["Cyklen har ligget på gaden i lang tid","Alle på gaden er stået op på samme tid","Der er nogen, som sidder på cyklen","Nogen har netop forladt cyklen"],"a":"Nogen har netop forladt cyklen","r":"Et hjul snurrer kun kort, så noget må lige være sket. Digtet viser kun sporet og overlader resten til læseren."},
{"l":6316,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"På bunden af søen ligger der 'sediment'. Hvad er det?","o":["materiale, der er sunket ned og lagt sig i lag","vand, der strømmer op fra kilder i søens bund","alger, der vokser ved vandets overflade","fisk, der lever helt nede ved bunden"],"a":"materiale, der er sunket ned og lagt sig i lag","r":"Sediment består af for eksempel sand, ler og dødt plantemateriale. Gennem lang tid kan lagene blive til sten."},
{"l":6338,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I et forsøg må du kun ændre én 'variabel' ad gangen. Hvad er en variabel?","o":["et resultat, der aldrig ændrer sig","en størrelse, der kan ændre sig","en fejl, der er sket under forsøget","et redskab, man måler med"],"a":"en størrelse, der kan ændre sig","r":"Det kan være temperatur, tid eller mængde. Hvis man kun ændrer én ad gangen, ved man, hvad der gav resultatet."},
{"l":6357,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt ind: 'Her er det ___ at parkere.'","o":["forbut","forbudet","forbudt","forbydt"],"a":"forbudt","r":"Tillægsformen af 'forbyde' skifter y til u og ender på -dt."},
{"l":6379,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs reklamen: 'Sprød. Sund. Sjov. Prøv vores nye knækbrød i dag!' Hvilket lydligt virkemiddel bruger den?","o":["metafor","personifikation","ironi","allitteration"],"a":"allitteration","r":"De tre ord begynder med samme lyd. Allitteration gør en reklame let at huske."},
{"l":6398,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Ingen kom til skade, da et træ i aftes væltede ned over cykelparkeringen ved Østerskolen. Ifølge pedellen har træet været sygt længe. Kommunen oplyser, at den ikke har modtaget nogen henvendelser om træet.' Hvad vil kommunen sige med sin oplysning?","o":["Den siger, at den ikke kendte til det","Den giver pedellen skylden for ulykken","Den lover at erstatte de ødelagte cykler","Den oplyser, hvornår træet blev plantet"],"a":"Den siger, at den ikke kendte til det","r":"Kommunen siger, at ingen har henvendt sig, og dermed at den ikke vidste noget. Den siger ikke direkte, hvem der har skylden."},
{"l":6420,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvad viser apostroffen i ordet sku' i sætningen: 'Det sku' du ikke have gjort.'?","o":["At ordet er lånt fra engelsk","At der er udeladt bogstaver","At ordet står i ejefald","At der kommer en pause"],"a":"At der er udeladt bogstaver","r":"'Sku'' er en talesprogsform af 'skulle', og apostroffen står for de bogstaver, der er faldet væk."},
{"l":6436,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Kommunen henstiller til, at hundeejere holder hunden i snor.' Hvad gør kommunen?","o":["straffer dem, der gør det","undersøger, hvor mange der gør det","beder høfligt om det","takker dem, der gør det"],"a":"beder høfligt om det","r":"At henstille er at bede om eller anbefale noget på en formel måde. Det er ikke et forbud eller en ordre."},
{"l":6460,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken skrivemåde er rigtig: 'Hun vandt ___ til stævnet.'? Det er et løb på 100 meter.","o":["100 meterløbet","100 meter løbet","100-meter-løbet","100-meterløbet"],"a":"100-meterløbet","r":"Når et tal sættes sammen med et ord, bruger man bindestreg efter tallet. Resten er ét sammensat ord og skrives i ét."},
{"l":6481,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Holdet satte alle sejl til i slutspurten.' Hvad gjorde holdet?","o":["gjorde alt, hvad det kunne","gav op før tid","sparede på kræfterne","rejste hjem med skib"],"a":"gjorde alt, hvad det kunne","r":"På et sejlskib sætter man alle sejl, når man vil have størst mulig fart. Talemåden betyder at sætte alle kræfter ind."},
{"l":6500,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord er forkert skrevet med stort: 'Vi fik besøg af Borgmester Larsen fra Esbjerg Kommune.'?","o":["Larsen","Borgmester","Esbjerg","Kommune"],"a":"Borgmester","r":"Titler skrives med lille foran navnet, mens Esbjerg Kommune er et officielt navn."},
{"l":6511,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I it-verdenen taler man om en 'trojansk hest'. Hvad er det?","o":["et program, der gør computeren meget hurtigere","en hjemmeside med spil om græske myter","et program, der ser uskyldigt ud, men er skadeligt","en kode, der låser din telefon op"],"a":"et program, der ser uskyldigt ud, men er skadeligt","r":"I myten narrede grækerne trojanerne med en træhest, hvor soldater gemte sig indeni. Programmet virker også harmløst, men har noget farligt skjult."},
{"l":6532,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord er sammensat af 'land' og et andet ord med bindebogstavet -e-?","o":["landsby","landmand","landkort","landevej"],"a":"landevej","r":"I 'landevej' bindes de to led sammen med -e-. 'Landsby' har et -s-, og 'landmand' og 'landkort' har ikke noget bindebogstav."},
{"l":6552,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvordan staves instrumentet med seks strenge, som man spiller på med fingrene?","o":["guitar","gitar","guittar","gitarr"],"a":"guitar","r":"Ordet stammer fra spansk og skrives med et u efter g'et, selvom det ikke høres."},
{"l":6573,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad får du, når du køber en 'aktie'?","o":["et lån til staten","en lille del af et firma","en opsparing med fast rente","et års garanti på firmaets varer"],"a":"en lille del af et firma","r":"En aktionær ejer en del af selskabet og kan tjene eller tabe penge, når det går op eller ned for det."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
